head.b:skin:
:root{--bg:#f4f1ec;--fg:#1a1a1a;--card:#fff;--line:#d9d4cb;--ac:#d71920;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#17171a;--fg:#f1f1f1;--card:#222226;--line:#3a3a40}}
:root[data-theme="dark"]{--bg:#17171a;--fg:#f1f1f1;--card:#222226;--line:#3a3a40}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font-family:"Noto Serif Bengali",serif}
.wrap{max-width:1000px;margin:0 auto;padding:16px;display:flex;flex-wrap:wrap;gap:20px;justify-content:center}
.pv{flex:1 1 340px;max-width:460px}canvas{width:100%;height:auto;border-radius:10px;box-shadow:0 6px 24px rgba(0,0,0,.25);background:#fff}
.ctl{flex:1 1 300px;max-width:460px;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px}
h1{font-size:20px;margin:0 0 12px;color:var(--ac)}label{display:block;font-size:14px;font-weight:700;margin:12px 0 4px}
textarea{width:100%;font:700 18px "Noto Serif Bengali",serif;padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--fg);resize:vertical}
input[type=range]{width:100%}.up{display:block;border:2px dashed var(--ac);border-radius:10px;padding:18px;text-align:center;cursor:pointer;font-weight:700}
.up.drag{background:rgba(215,25,32,.1)}button{width:100%;margin-top:16px;padding:13px;border:0;border-radius:8px;background:var(--ac);color:#fff;font:700 17px "Noto Serif Bengali",serif;cursor:pointer}
small{display:block;margin-top:8px;opacity:.7;font-size:12px}

body.script:
//

const W=1080,H=1350,PH=780,RED="#d71920",$=i=>document.getElementById(i);
const cv=$("c"),ctx=cv.getContext("2d");let photo=null;const logo=new Image();
const bn=s=>String(s).replace(/\d/g,d=>"০১২৩৪৫৬৭৮৯"[d]);
const DAYS=["রবিবার","সোমবার","মঙ্গলবার","বুধবার","বৃহস্পতিবার","শুক্রবার","শনিবার"];
const MON=["জানুয়ারি","ফেব্রুয়ারি","মার্চ","এপ্রিল","মে","জুন","জুলাই","আগস্ট","সেপ্টেম্বর","অক্টোবর","নভেম্বর","ডিসেম্বর"];
function today(){const d=new Date(new Date().toLocaleString("en-US",{timeZone:"Asia/Dhaka"}));return{day:DAYS[d.getDay()],date:bn(d.getDate())+" "+MON[d.getMonth()]+" "+bn(d.getFullYear())}}
function lines(t){let L=t.split("\n").map(x=>x.trim()).filter(Boolean);if(L.length>2)L=[L[0],L.slice(1).join(" ")];
if(L.length==1){const w=L[0].split(/\s+/);if(w.length>1){const tot=L[0].length;let best=1,bd=1e9;for(let i=1;i<w.length;i++){const d=Math.abs(w.slice(0,i).join(" ").length-tot/2);if(d<bd){bd=d;best=i}}L=[w.slice(0,best).join(" "),w.slice(best).join(" ")]}}return L}
function fit(L,maxW){let s=88;while(s>38){ctx.font="800 "+s+"px 'Noto Serif Bengali',serif";if(L.every(l=>ctx.measureText(l).width<=maxW))break;s-=2}return s}
function draw(){
ctx.clearRect(0,0,W,H);ctx.fillStyle="#fbf8f3";ctx.fillRect(0,0,W,H);
ctx.save();ctx.beginPath();ctx.rect(0,0,W,PH);ctx.clip();
if(photo){const s=Math.max(W/photo.width,PH/photo.height)*$("z").value;const w=photo.width*s,h=photo.height*s;
ctx.drawImage(photo,(W-w)/2+$("x").value*W*.005,(PH-h)/2+$("y").value*PH*.005,w,h)}
else{const g=ctx.createLinearGradient(0,0,W,PH);g.addColorStop(0,"#3a3a40");g.addColorStop(1,"#1b1b1f");ctx.fillStyle=g;ctx.fillRect(0,0,W,PH);
ctx.fillStyle="#aaa";ctx.font="700 44px 'Noto Serif Bengali',serif";ctx.textAlign="center";ctx.fillText("এখানে ছবি বসবে",W/2,PH/2)}
ctx.restore();
if(logo.complete&&logo.naturalWidth){const lh=64,lw=lh*logo.naturalWidth/logo.naturalHeight,bw=lw+36,bh=lh+30,bx=W-bw-28,by=28;
ctx.save();ctx.shadowColor="rgba(0,0,0,.3)";ctx.shadowBlur=16;ctx.shadowOffsetY=4;ctx.fillStyle="#fff";ctx.beginPath();ctx.roundRect(bx,by,bw,bh,16);ctx.fill();ctx.restore();ctx.drawImage(logo,bx+18,by+15,lw,lh)}
ctx.fillStyle=RED;ctx.fillRect(0,PH,W,8);
const L=lines($("t").value),s=fit(L,940),lh2=s*1.4;
ctx.textAlign="center";ctx.fillStyle="#141414";ctx.font="800 "+s+"px 'Noto Serif Bengali',serif";
const y0=1005-(L.length-1)*lh2/2+s*.3;L.forEach((l,i)=>ctx.fillText(l,W/2,y0+i*lh2));
const dt=today(),dtx=dt.day+"  •  "+dt.date;
ctx.font="700 32px 'Noto Serif Bengali',serif";const tw=ctx.measureText(dtx).width;
ctx.font="700 36px 'Hind Siliguri',Arial,sans-serif";const wt="DailySakalbela.com",ww=ctx.measureText(wt).width;
const gap=60,iw=48,pw=tw+gap+iw+12+ww+100,px=(W-pw)/2,py=1232,ph=84,cy=py+ph/2,cx=px+50;
ctx.fillStyle=RED;ctx.beginPath();ctx.roundRect(px,py,pw,ph,42);ctx.fill();
ctx.fillStyle="#fff";ctx.textAlign="left";ctx.font="700 32px 'Noto Serif Bengali',serif";ctx.fillText(dtx,cx,cy+11);
ctx.fillStyle="rgba(255,255,255,.55)";ctx.fillRect(cx+tw+gap/2-1.5,py+20,3,ph-40);
const gx=cx+tw+gap+24;ctx.strokeStyle="#fff";ctx.lineWidth=3;ctx.beginPath();ctx.arc(gx,cy,22,0,7);ctx.stroke();
ctx.beginPath();ctx.ellipse(gx,cy,9,22,0,0,7);ctx.stroke();ctx.beginPath();ctx.moveTo(gx-22,cy);ctx.lineTo(gx+22,cy);ctx.moveTo(gx-18,cy-11);ctx.lineTo(gx+18,cy-11);ctx.moveTo(gx-18,cy+11);ctx.lineTo(gx+18,cy+11);ctx.stroke();
ctx.fillStyle="#fff";ctx.font="700 36px 'Hind Siliguri',Arial,sans-serif";ctx.fillText(wt,gx+36,cy+12)}
function load(file){if(!file)return;const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{photo=i;$("z").value=1;$("x").value=0;$("y").value=0;draw()};i.src=r.result};r.readAsDataURL(file)}
$("f").onchange=e=>load(e.target.files[0]);
const dz=$("dz");["dragover","dragenter"].forEach(n=>dz.addEventListener(n,e=>{e.preventDefault();dz.classList.add("drag")}));
["dragleave","drop"].forEach(n=>dz.addEventListener(n,e=>{e.preventDefault();dz.classList.remove("drag")}));
dz.addEventListener("drop",e=>load(e.dataTransfer.files[0]));
["t","z","x","y"].forEach(i=>$(i).addEventListener("input",draw));
$("d").onclick=()=>{cv.toBlob(b=>{const a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="sakalbela-photocard.png";document.body.appendChild(a);a.click();a.remove()},"image/png")};
logo.onload=draw;logo.src="data:image/png;base64,";draw();
Promise.all([document.fonts.load("800 60px 'Noto Serif Bengali'","অআকখ"),document.fonts.load("700 36px 'Noto Serif Bengali'","অআকখ"),document.fonts.load("700 40px 'Hind Siliguri'","Daily")]).then(draw).catch(()=>{});

//
